import{_ as t,o as d,c as a,ag as o}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/storage/commands.md","filePath":"modules/storage/commands.md","lastUpdated":null}'),s={name:"modules/storage/commands.md"};function c(r,e,n,l,i,p){return d(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>EmakiStorage 的主命令是 <code>/emakistorage</code>，别名为 <code>/estorage</code>。文档示例统一使用 <code>/estorage</code>。</p><p>不带参数执行时打开自己的仓库，需要 <code>emakistorage.use</code>（<code>emakistorage.admin</code> 也可通过）。管理类子命令统一要求 <code>emakistorage.admin</code>；<code>reload</code> 与 <code>debug</code> 另有专用权限，也可被 <code>emakistorage.admin</code> 代替。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to &quot;命令列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/estorage</code></td><td><code>emakistorage.use</code></td><td>打开自己的仓库。仅玩家可执行。</td></tr><tr><td><code>/estorage help</code></td><td>无额外检查</td><td>显示帮助。</td></tr><tr><td><code>/estorage open &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>以管理员身份打开目标玩家的仓库。执行者必须是玩家。</td></tr><tr><td><code>/estorage slot grant &lt;player&gt; &lt;amount&gt;</code></td><td><code>emakistorage.admin</code></td><td>调整目标玩家的授予槽位数。<code>amount</code> 为负数表示回收。</td></tr><tr><td><code>/estorage stacklimit player &lt;player&gt; &lt;limit&gt;</code></td><td><code>emakistorage.admin</code></td><td>设置目标玩家的玩家级单槽上限。</td></tr><tr><td><code>/estorage stacklimit slot &lt;player&gt; &lt;slot&gt; &lt;limit&gt;</code></td><td><code>emakistorage.admin</code></td><td>设置目标玩家某个逻辑槽位的条目级上限。</td></tr><tr><td><code>/estorage info &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>打印容量拆解、页数、<code>stackLimit</code>、排序模式与总量。</td></tr><tr><td><code>/estorage export &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>把仓库导出为可读 YAML，写入 <code>exports/export-&lt;uuid&gt;.yml</code>。</td></tr><tr><td><code>/estorage reload</code></td><td><code>emakistorage.reload</code> 或 <code>emakistorage.admin</code></td><td>重载配置、语言与 GUI 模板，并回报已加载模板数。</td></tr><tr><td><code>/estorage debug ...</code></td><td><code>emakistorage.debug</code> 或 <code>emakistorage.admin</code></td><td>管理 debug 模块。可用模块为 <code>storage</code> 与 <code>chat_input</code>，具体子命令由 CoreLib DebugCommand 提供。</td></tr></tbody></table><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/estorage</span></span>
<span class="line"><span>/estorage help</span></span>
<span class="line"><span>/estorage open Steve</span></span>
<span class="line"><span>/estorage slot grant Steve 10</span></span>
<span class="line"><span>/estorage slot grant Steve -5</span></span>
<span class="line"><span>/estorage stacklimit player Steve 100000</span></span>
<span class="line"><span>/estorage stacklimit player Steve max</span></span>
<span class="line"><span>/estorage stacklimit player Steve 10k</span></span>
<span class="line"><span>/estorage stacklimit slot Steve 3 5000</span></span>
<span class="line"><span>/estorage info Steve</span></span>
<span class="line"><span>/estorage export Steve</span></span>
<span class="line"><span>/estorage reload</span></span>
<span class="line"><span>/estorage debug storage on</span></span></code></pre></div><h2 id="参数写法" tabindex="-1">参数写法 <a class="header-anchor" href="#参数写法" aria-label="Permalink to &quot;参数写法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>接受的写法</th><th>说明</th></tr></thead><tbody><tr><td><code>&lt;amount&gt;</code>（slot grant）</td><td>十进制整数，可为负</td><td>负值回收授予槽位。</td></tr><tr><td><code>&lt;limit&gt;</code>（stacklimit）</td><td>十进制数字、紧凑单位（<code>k</code> <code>m</code> <code>b</code> <code>t</code> <code>p</code> <code>e</code>）、<code>max</code></td><td><code>max</code> 解析为 <code>Long.MAX_VALUE</code>。溢出与 <code>&lt;= 0</code> 一律拒绝而不截断，避免手误静默变成另一个上限。因此命令层无法填 <code>0</code>，恢复继承请用 API 或 Action。</td></tr><tr><td><code>&lt;slot&gt;</code></td><td>逻辑槽位索引（0 起）</td><td>该槽位没有条目时命令回报「槽位为空」，不会创建条目。</td></tr></tbody></table><h2 id="写操作要求目标玩家在线" tabindex="-1">写操作要求目标玩家在线 <a class="header-anchor" href="#写操作要求目标玩家在线" aria-label="Permalink to &quot;写操作要求目标玩家在线&quot;">​</a></h2><p><code>slot grant</code> 与 <code>stacklimit</code> 两类写操作在目标玩家离线时直接拒绝，回报 <code>command.target_offline</code>。原因是这些操作要改的是内存中已加载的仓库对象：直接改写一个未加载的存档会与该玩家下一次登录时的载入流程产生竞态，可能覆盖或丢弃改动。</p><p>在线目标的写操作会被派发到该玩家自己的 region 线程执行，而不是命令执行者所在的线程。如果此时该玩家的仓库数据仍在载入，命令回报 <code>general.data_loading</code>，请稍后重试。</p><p>只读类命令没有这个限制：<code>info</code> 与 <code>export</code> 走快照读取路径，可以在必要时从磁盘载入数据，因此对离线玩家同样可用。<code>open &lt;player&gt;</code> 也可用于离线目标。</p><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to &quot;权限节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>覆盖范围</th></tr></thead><tbody><tr><td><code>emakistorage.use</code></td><td><code>true</code></td><td>打开自己的仓库。</td></tr><tr><td><code>emakistorage.unlock.purchase</code></td><td><code>true</code></td><td>在 GUI 中使用付费扩容。还需 <code>unlock.purchase_enabled: true</code>。</td></tr><tr><td><code>emakistorage.reload</code></td><td><code>op</code></td><td>使用 <code>/estorage reload</code>。可被 <code>emakistorage.admin</code> 代替。</td></tr><tr><td><code>emakistorage.debug</code></td><td><code>op</code></td><td>使用 <code>/estorage debug ...</code>。可被 <code>emakistorage.admin</code> 代替。</td></tr><tr><td><code>emakistorage.admin</code></td><td><code>op</code></td><td>使用 <code>open</code>、<code>slot</code>、<code>stacklimit</code>、<code>info</code>、<code>export</code>，并可代替 reload/debug 专用权限。</td></tr></tbody></table><h2 id="数值档位权限" tabindex="-1">数值档位权限 <a class="header-anchor" href="#数值档位权限" aria-label="Permalink to &quot;数值档位权限&quot;">​</a></h2><p>以下两个权限是<strong>数值档位</strong>，不在 <code>paper-plugin.yml</code> 中声明，直接授予带数字后缀的节点即可。</p><table tabindex="0"><thead><tr><th>权限前缀</th><th>作用</th><th>取值规则</th></tr></thead><tbody><tr><td><code>emakistorage.slots.&lt;n&gt;</code></td><td>追加 <code>n</code> 个槽位</td><td>扫描玩家所有生效权限，取数字后缀的<strong>最大值</strong>，不累加。</td></tr><tr><td><code>emakistorage.stacklimit.&lt;n&gt;</code></td><td>提供玩家级单槽上限 <code>n</code></td><td>同样取最大值。</td></tr></tbody></table><p>两者都<strong>不支持通配</strong>：<code>emakistorage.slots.*</code> 之类的写法会被跳过。部分权限插件会把通配展开成「持有每一个 n」，那样会把玩家静默推到最高档；因此实现只接受纯数字后缀，含 <code>.</code> 或非数字的后缀一律忽略。</p><p>常见 LuckPerms 示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/lp group default permission set emakistorage.use true</span></span>
<span class="line"><span>/lp group default permission set emakistorage.unlock.purchase true</span></span>
<span class="line"><span>/lp group vip permission set emakistorage.slots.100 true</span></span>
<span class="line"><span>/lp group vip permission set emakistorage.stacklimit.100000 true</span></span>
<span class="line"><span>/lp group admin permission set emakistorage.admin true</span></span></code></pre></div><h2 id="reload-行为" tabindex="-1">reload 行为 <a class="header-anchor" href="#reload-行为" aria-label="Permalink to &quot;reload 行为&quot;">​</a></h2><p><code>/estorage reload</code> 会执行以下工作：</p><ol><li>释放缺失的默认资源，受 <code>config.yml &gt; release_default_data</code> 控制。</li><li>重新读取 <code>config.yml</code>、<code>lang/*.yml</code>、<code>unlock_costs.yml</code> 与 <code>gui/storage_gui.yml</code>。</li><li>按新的 <code>gui.storage_rows</code> 重新换算 GUI 布局。</li><li>回报已加载的界面模板数量。</li></ol><p><code>gui.storage_rows</code> 超出 1–5 时会被钳制并在控制台记 warning，见 <a href="./configuration.html">配置详解</a>。</p><h2 id="常见失败原因" tabindex="-1">常见失败原因 <a class="header-anchor" href="#常见失败原因" aria-label="Permalink to &quot;常见失败原因&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>说明</th></tr></thead><tbody><tr><td><code>找不到玩家</code></td><td>玩家名不精确匹配，且服务器缓存中也没有该离线玩家。</td></tr><tr><td><code>玩家 ... 当前离线，无法执行该写操作</code></td><td><code>slot grant</code> / <code>stacklimit</code> 的目标必须在线。</td></tr><tr><td><code>仓库数据仍在加载，请稍后再试</code></td><td>目标在线但其仓库尚未载入完成。</td></tr><tr><td><code>槽位为空</code></td><td><code>stacklimit slot</code> 指定的逻辑槽位当前没有条目。</td></tr><tr><td><code>stacklimit</code> 参数被拒绝</td><td>解析结果 <code>&lt;= 0</code> 或超出 <code>long</code> 范围。请使用正整数、紧凑单位或 <code>max</code>。</td></tr><tr><td><code>仓库界面打开失败</code></td><td>GUI 模板未加载或解析失败，检查控制台 warning。</td></tr></tbody></table>`,27)])])}const h=t(s,[["render",c]]);export{m as __pageData,h as default};
